-- Numeric School Custom academic truth. Publisher curriculum and grading rules are out of scope.
begin;
create table app.school_custom_versions(
 school_id uuid not null,id uuid not null default gen_random_uuid(),version text not null check(length(version) between 1 and 100),source_type text not null default 'SCHOOL_AUTHORED' check(source_type='SCHOOL_AUTHORED'),rights_status text not null default 'PERMITTED' check(rights_status='PERMITTED'),created_by uuid not null,created_at timestamptz not null default clock_timestamp(),
 primary key(school_id,id),foreign key(school_id,created_by) references app.memberships(school_id,actor_id)
);
create table app.school_custom_references(
 school_id uuid not null,id uuid not null default gen_random_uuid(),version_id uuid not null,title text not null check(length(title) between 1 and 200),description text not null check(length(description) between 1 and 4000),code text check(code is null),status text not null default 'DRAFT' check(status in('DRAFT','APPROVED')),created_by uuid not null,approved_by uuid,approved_at timestamptz,created_at timestamptz not null default clock_timestamp(),
 primary key(school_id,id),foreign key(school_id,version_id) references app.school_custom_versions(school_id,id),foreign key(school_id,created_by) references app.memberships(school_id,actor_id),foreign key(school_id,approved_by) references app.memberships(school_id,actor_id),check((status='DRAFT' and approved_by is null and approved_at is null)or(status='APPROVED' and approved_by is not null and approved_at is not null))
);
create index school_refs_version_idx on app.school_custom_references(school_id,version_id);
alter table app.assessments add column academic_reference_id uuid;
alter table app.assessments add column model text not null default 'numeric' check(model='numeric');
alter table app.assessments add foreign key(school_id,academic_reference_id) references app.school_custom_references(school_id,id);
do $$declare constraint_name text;begin for constraint_name in select conname from pg_constraint where conrelid='app.assessments'::regclass and contype='c' and pg_get_constraintdef(oid) like '%policy_version%' loop execute format('alter table app.assessments drop constraint %I',constraint_name);end loop;end$$;
alter table app.assessments add check(policy_version>=1);
alter table app.submissions add unique(school_id,id,learner_id);
create table app.marking_revisions(
 school_id uuid not null,id uuid not null default gen_random_uuid(),submission_id uuid not null,learner_id uuid not null,revision integer not null check(revision>0),score numeric not null,max_score numeric not null,feedback text not null check(length(feedback)<=10000),policy_version integer not null,reference_id uuid,source_object_id uuid not null,created_by uuid not null,created_at timestamptz not null default clock_timestamp(),
 primary key(school_id,id),unique(school_id,id,learner_id),unique(school_id,submission_id,revision),foreign key(school_id,submission_id,learner_id) references app.submissions(school_id,id,learner_id),foreign key(school_id,reference_id) references app.school_custom_references(school_id,id),foreign key(school_id,created_by) references app.memberships(school_id,actor_id),check(score>=0 and score<=max_score and max_score>0 and max_score<=100000),check(source_object_id=submission_id),check(policy_version>0)
);
create table app.result_revisions(
 school_id uuid not null,id uuid not null default gen_random_uuid(),marking_id uuid not null,submission_id uuid not null,assessment_id uuid not null,learner_id uuid not null,revision integer not null,score numeric not null,max_score numeric not null,feedback text not null,policy_version integer not null,reference_id uuid not null,reference_version text not null,evidence_id uuid not null,parent_visible boolean not null default false,created_by uuid not null,created_at timestamptz not null default clock_timestamp(),previous_result_id uuid,
 primary key(school_id,id),unique(school_id,id,learner_id),unique(school_id,id,submission_id,learner_id),unique(school_id,marking_id),foreign key(school_id,marking_id,learner_id) references app.marking_revisions(school_id,id,learner_id),foreign key(school_id,submission_id,learner_id) references app.submissions(school_id,id,learner_id),foreign key(school_id,assessment_id) references app.assessments(school_id,id),foreign key(school_id,reference_id) references app.school_custom_references(school_id,id),foreign key(school_id,created_by) references app.memberships(school_id,actor_id),foreign key(school_id,previous_result_id) references app.result_revisions(school_id,id),check(revision>0 and score>=0 and score<=max_score)
);
create table app.academic_evidence(
 school_id uuid not null,id uuid not null default gen_random_uuid(),source_type text not null default 'SUBMISSION' check(source_type='SUBMISSION'),source_object_id uuid not null,learner_id uuid not null,actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),quality text not null default 'TEACHER_ENTERED' check(quality='TEACHER_ENTERED'),reference_id uuid not null,reference_version text not null,policy_version integer not null,result_id uuid not null,revision integer not null,parent_visible boolean not null default false,review_status text not null default 'APPROVED' check(review_status='APPROVED'),
 primary key(school_id,id),foreign key(school_id,source_object_id,learner_id) references app.submissions(school_id,id,learner_id),foreign key(school_id,result_id,learner_id) references app.result_revisions(school_id,id,learner_id) deferrable initially deferred,foreign key(school_id,reference_id) references app.school_custom_references(school_id,id),foreign key(school_id,actor_id) references app.memberships(school_id,actor_id)
);
alter table app.result_revisions add foreign key(school_id,evidence_id) references app.academic_evidence(school_id,id) deferrable initially deferred;
create table app.current_results(
 school_id uuid not null,submission_id uuid not null,learner_id uuid not null,result_id uuid not null,updated_at timestamptz not null default clock_timestamp(),primary key(school_id,submission_id),foreign key(school_id,result_id,submission_id,learner_id) references app.result_revisions(school_id,id,submission_id,learner_id)
);
create index marks_submission_idx on app.marking_revisions(school_id,submission_id,revision desc);
create index results_learner_idx on app.result_revisions(school_id,learner_id,id);
create index evidence_learner_idx on app.academic_evidence(school_id,learner_id,id);
create function "authorization".academic_access(target_school uuid) returns boolean language sql stable security definer set search_path='' as $$select coalesce("authorization".can_access_school(target_school) and "authorization".has_entitlement(target_school,'assessment') and "authorization".has_entitlement(target_school,'curriculum'),false)$$;
create function "authorization".can_mark_submission(target_school uuid,target_submission uuid) returns boolean language sql stable security definer set search_path='' as $$
select coalesce("authorization".academic_access(target_school) and "authorization".current_role(target_school) in('teacher','admin') and exists(select 1 from app.submissions s join app.assessments a on a.school_id=s.school_id and a.id=s.assessment_id where s.school_id=target_school and s.id=target_submission and "authorization".can_manage_course(target_school,a.course_id) and "authorization".can_view_person(target_school,s.learner_id) and exists(select 1 from app.courses c join app.enrollments e on e.school_id=c.school_id and e.class_id=c.class_id where c.school_id=target_school and c.id=a.course_id and e.student_actor_id=s.learner_id and e.status='active' and e.effective_from<=now() and(e.effective_to is null or e.effective_to>now()))),false)
$$;
create function "authorization".can_read_academic(target_school uuid,target_learner uuid,parent_allowed boolean) returns boolean language sql stable security definer set search_path='' as $$select coalesce("authorization".academic_access(target_school) and "authorization".can_view_person(target_school,target_learner) and("authorization".current_role(target_school)<>'parent' or parent_allowed is true),false)$$;
create function internal.academic_require() returns void language plpgsql security definer set search_path='' as $$begin if not "authorization".academic_access("authorization".school_id()) then raise exception 'Academic access required' using errcode='42501';end if;end$$;
create function internal.create_school_reference(ref_title text,ref_description text,ref_version text) returns uuid language plpgsql security definer set search_path='' as $$
declare vid uuid;rid uuid;begin perform internal.academic_require();if "authorization".current_role("authorization".school_id()) not in('teacher','admin') then raise exception 'Reference author denied' using errcode='42501';end if;
insert into app.school_custom_versions(school_id,version,created_by)values("authorization".school_id(),ref_version,"authorization".actor_id())returning id into vid;
insert into app.school_custom_references(school_id,version_id,title,description,created_by)values("authorization".school_id(),vid,ref_title,ref_description,"authorization".actor_id())returning id into rid;return rid;end$$;
create function internal.approve_school_reference(target_reference uuid) returns uuid language plpgsql security definer set search_path='' as $$begin perform internal.academic_require();if "authorization".current_role("authorization".school_id()) not in('coordinator','admin') then raise exception 'Reference approval denied' using errcode='42501';end if;
update app.school_custom_references set status='APPROVED',approved_by="authorization".actor_id(),approved_at=clock_timestamp() where school_id="authorization".school_id() and id=target_reference and status='DRAFT';if not found and not exists(select 1 from app.school_custom_references where school_id="authorization".school_id() and id=target_reference and status='APPROVED')then raise exception 'Reference unavailable' using errcode='22023';end if;return target_reference;end$$;
create function internal.link_assessment_reference(target_assessment uuid,target_reference uuid,expected_policy integer) returns void language plpgsql security definer set search_path='' as $$declare a app.assessments;begin perform internal.academic_require();select * into a from app.assessments where school_id="authorization".school_id() and id=target_assessment for update;if not found or not "authorization".can_manage_course(a.school_id,a.course_id)then raise exception 'Assessment denied' using errcode='42501';end if;
if expected_policy is null or a.policy_version<>expected_policy or exists(select 1 from app.marking_revisions m join app.submissions s on s.school_id=m.school_id and s.id=m.submission_id where s.school_id=a.school_id and s.assessment_id=a.id)then raise exception 'Assessment context frozen or changed' using errcode='22023';end if;
if not exists(select 1 from app.school_custom_references where school_id=a.school_id and id=target_reference and status='APPROVED')then raise exception 'Approved reference required' using errcode='22023';end if;
update app.assessments set academic_reference_id=target_reference,policy_version=policy_version+1 where school_id=a.school_id and id=a.id;end$$;
create function internal.mark_submission(target_submission uuid,mark_score numeric,mark_feedback text,expected_policy integer,expected_revision integer,source_evidence boolean) returns uuid language plpgsql security definer set search_path='' as $$
declare s app.submissions;a app.assessments;latest integer;mid uuid;begin perform internal.academic_require();if not "authorization".can_mark_submission("authorization".school_id(),target_submission)then raise exception 'Marking denied' using errcode='42501';end if;
select * into s from app.submissions where school_id="authorization".school_id() and id=target_submission for update;select * into a from app.assessments where school_id=s.school_id and id=s.assessment_id for share;select coalesce(max(revision),0) into latest from app.marking_revisions where school_id=s.school_id and submission_id=s.id;
if mark_score is null or mark_score<0 or mark_score>a.max_score or expected_policy is null or expected_policy<>a.policy_version or expected_revision is null or expected_revision<>latest or source_evidence is distinct from true then raise exception 'Invalid or stale marking context' using errcode='22023';end if;
insert into app.marking_revisions(school_id,submission_id,learner_id,revision,score,max_score,feedback,policy_version,reference_id,source_object_id,created_by)values(s.school_id,s.id,s.learner_id,latest+1,mark_score,a.max_score,mark_feedback,a.policy_version,a.academic_reference_id,s.id,"authorization".actor_id())returning id into mid;return mid;end$$;
create function internal.release_marking(target_marking uuid,expected_revision integer,parent_allowed boolean) returns uuid language plpgsql security definer set search_path='' as $$
declare m app.marking_revisions;s app.submissions;a app.assessments;ref app.school_custom_references;v app.school_custom_versions;rid uuid;eid uuid:=gen_random_uuid();previous uuid;begin perform internal.academic_require();select * into m from app.marking_revisions where school_id="authorization".school_id() and id=target_marking;if not found or not "authorization".can_mark_submission(m.school_id,m.submission_id)then raise exception 'Release denied' using errcode='42501';end if;
select * into s from app.submissions where school_id=m.school_id and id=m.submission_id for update;select * into a from app.assessments where school_id=s.school_id and id=s.assessment_id for share;
if expected_revision is null or m.revision<>expected_revision or m.revision<>(select max(revision)from app.marking_revisions where school_id=m.school_id and submission_id=m.submission_id)or a.policy_version<>m.policy_version or a.academic_reference_id is distinct from m.reference_id or m.source_object_id<>s.id or parent_allowed is null then raise exception 'Stale release context' using errcode='22023';end if;
select * into ref from app.school_custom_references where school_id=m.school_id and id=m.reference_id and status='APPROVED';if not found then raise exception 'Approved source reference required' using errcode='22023';end if;select * into v from app.school_custom_versions where school_id=ref.school_id and id=ref.version_id;
select id into rid from app.result_revisions where school_id=m.school_id and marking_id=m.id;if found then if (select parent_visible from app.result_revisions where school_id=m.school_id and id=rid)is distinct from parent_allowed then raise exception 'Released visibility immutable' using errcode='22023';end if;return rid;end if;
select result_id into previous from app.current_results where school_id=m.school_id and submission_id=s.id;
rid:=gen_random_uuid();insert into app.result_revisions(school_id,id,marking_id,submission_id,assessment_id,learner_id,revision,score,max_score,feedback,policy_version,reference_id,reference_version,evidence_id,parent_visible,created_by,previous_result_id)values(m.school_id,rid,m.id,s.id,a.id,m.learner_id,m.revision,m.score,m.max_score,m.feedback,m.policy_version,ref.id,v.version,eid,parent_allowed,"authorization".actor_id(),previous);
insert into app.academic_evidence(school_id,id,source_object_id,learner_id,actor_id,reference_id,reference_version,policy_version,result_id,revision,parent_visible)values(m.school_id,eid,s.id,m.learner_id,"authorization".actor_id(),ref.id,v.version,m.policy_version,rid,m.revision,parent_allowed);
insert into app.current_results(school_id,submission_id,learner_id,result_id)values(m.school_id,s.id,m.learner_id,rid)on conflict(school_id,submission_id)do update set result_id=excluded.result_id,updated_at=clock_timestamp();return rid;end$$;
create function internal.academic_history_immutable() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Academic history is immutable' using errcode='55000';end$$;
do $$declare tab text;begin foreach tab in array array['school_custom_versions','school_custom_references','marking_revisions','result_revisions','academic_evidence','current_results']loop execute format('alter table app.%I enable row level security',tab);execute format('alter table app.%I force row level security',tab);end loop;foreach tab in array array['school_custom_versions','marking_revisions','result_revisions','academic_evidence']loop execute format('create trigger history_immutable before update or delete on app.%I for each row execute function internal.academic_history_immutable()',tab);execute format('create trigger history_no_truncate before truncate on app.%I for each statement execute function internal.academic_history_immutable()',tab);end loop;end$$;
create policy custom_versions_read on app.school_custom_versions for select to cuevo_api using("authorization".academic_access(school_id));
create policy custom_references_read on app.school_custom_references for select to cuevo_api using("authorization".academic_access(school_id)and(status='APPROVED'or"authorization".current_role(school_id)in('admin','coordinator','teacher')));
create policy markings_read on app.marking_revisions for select to cuevo_api using("authorization".can_mark_submission(school_id,submission_id));
create policy results_read on app.result_revisions for select to cuevo_api using("authorization".can_read_academic(school_id,learner_id,parent_visible));
create policy evidence_read on app.academic_evidence for select to cuevo_api using("authorization".can_read_academic(school_id,learner_id,parent_visible));
create policy current_results_read on app.current_results for select to cuevo_api using("authorization".can_read_academic(school_id,learner_id,(select r.parent_visible from app.result_revisions r where r.school_id=current_results.school_id and r.id=current_results.result_id)));
revoke all on app.school_custom_versions,app.school_custom_references,app.marking_revisions,app.result_revisions,app.academic_evidence,app.current_results from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant select on app.school_custom_versions,app.school_custom_references,app.marking_revisions,app.result_revisions,app.academic_evidence,app.current_results to cuevo_api;
revoke execute on function "authorization".academic_access(uuid),"authorization".can_mark_submission(uuid,uuid),"authorization".can_read_academic(uuid,uuid,boolean) from public,anon,authenticated,service_role,cuevo_worker;
grant execute on function "authorization".academic_access(uuid),"authorization".can_mark_submission(uuid,uuid),"authorization".can_read_academic(uuid,uuid,boolean) to cuevo_api;
revoke execute on function internal.academic_require(),internal.academic_history_immutable(),internal.create_school_reference(text,text,text),internal.approve_school_reference(uuid),internal.link_assessment_reference(uuid,uuid,integer),internal.mark_submission(uuid,numeric,text,integer,integer,boolean),internal.release_marking(uuid,integer,boolean) from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.create_school_reference(text,text,text),internal.approve_school_reference(uuid),internal.link_assessment_reference(uuid,uuid,integer),internal.mark_submission(uuid,numeric,text,integer,integer,boolean),internal.release_marking(uuid,integer,boolean) to cuevo_api;
commit;
